// MauvilleCity_Gym (zone 239): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0304_room_MauvilleCity_Gym.txt
// Story (chapter Ch3 part 3b, ch3b agent 2026-10-07; Sapphire data/maps/MauvilleCity_Gym/scripts.inc) after the
// "// ---- story" line: scripts 2-8, text lines 1-10 (line 0 is the generator's). Wattson (uid 1), the Gym guide
// (uid 6), the two statues' plaques, the three floor switches (step triggers that always fire, as Sapphire's
// VAR_TEMP_0 0 coord events) and the four trainers (Shawn uid 2, Vivian 3, Ben 4, Kirk 5: Black 2's eye-contact
// trainer script 3000 + id) are in data/story/ch3b.json. Map scripts: 0479_room_MauvilleCity_Gym_init.s (zone init =
// script 8). Room origin (1,0): zone tile = Sapphire tile + (1,0).
#include "asm/field_script.inc"
#include "hoenn.h"  // ch3b
#include "hoenn_trainers.h"  // ch3b
#include "hoenn_story.inc"  // ch3b
#include "scenes/ch3b_lib.inc"  // ch3b

    ScriptEntry Script_None
    ScriptEntry MG_Wattson          // 2: MauvilleCity_Gym_EventScript_Wattson  // story:
    ScriptEntry MG_GymGuide         // 3: MauvilleCity_Gym_EventScript_GymGuide  // story:
    ScriptEntry MG_GymStatue        // 4: MauvilleCity_Gym_EventScript_LeftGymStatue / RightGymStatue  // story:
    ScriptEntry MG_Switch1          // 5: MauvilleCity_Gym_EventScript_Switch1, (0,9)  // story:
    ScriptEntry MG_Switch2          // 6: MauvilleCity_Gym_EventScript_Switch2, (8,11)  // story:
    ScriptEntry MG_Switch3          // 7: MauvilleCity_Gym_EventScript_Switch3, (4,15)  // story:
    ScriptEntry MG_ZoneInit         // 8: MauvilleCity_Gym_OnLoad  // story:
    ScriptEntry MG_FadeIn           // 9: after Sub_MG_Redraw's map change (story_fixups)  // story:
// >>> emerald_rooms mauville_entries (b2tools/emerald_rooms.py / emerald_gyms.py write this block on every run: edit the generator)
#ifdef HOENN_EMERALD
    ScriptEntry MG_Switch4Em        // 10: MauvilleCity_Gym_EventScript_Switch4, (8,9) (Emerald only)
#endif
// <<< emerald_rooms mauville_entries
    ScriptEntriesEnd

Script_None:
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch3 part 3b, ch3b agent: Sapphire's story scripts of this room; generators must keep
// everything from this line on; entries above marked "// story:")
// The barriers. Sapphire redraws the electric beams with setmetatile (MauvilleGymSpecial1/2/3) and their collision
// changes with them: two layouts while Wattson is unbeaten (FLAG_MAUVILLE_GYM_BARRIERS_STATE clear/set, toggled by
// every switch press) and a third with every beam off once he is beaten. Black 2 maps are 3D models with baked
// collision and no script command changes collision; its way to swap a room's layout is a map replacement (a/0/1/0,
// MapReplaceSetEvent; Shoal Cave's tides, notes/CAVES.md "alt_rooms"). b2tools/gyms_league_rooms.py builds the three
// (story_fixups 2026-10-07): MauvilleCity_Gym = Sapphire's map (FLAG clear: beams at (4,8) (5,8) (3,9) (3,10) (6,12)
// (6,13) (4,14) (5,14)), MauvilleCity_Gym_Alt = MauvilleGymSpecial2 on it (beams at (1,11) (2,11) (3,12) (3,13) (4,11)
// (5,11)), MauvilleCity_Gym_Off = MauvilleGymSpecial3 (no beams); data/interiors/239.json "alt_rooms" loads the alt or
// off room's matrix instead of the room's while map replace event MG_EVENT_ALT / MG_EVENT_OFF is set (works 0x4034 /
// 0x4035: data/story_ids.json WORK_MAP_REPLACE_3/4). MG_SHOW_LAYOUT sets them for Sapphire's state.
#define MG_EVENT_ALT 3                  /* map replace event 3 (work 0x4034 == 0x1209): the barriers swapped */
#define MG_EVENT_OFF 4                  /* map replace event 4 (work 0x4035 == 0x316): every barrier off */
#define MG_REDRAW 0x8050                /* scratch works of Sub_MG_Redraw (Black 2 scripts use 0x8050-0x8052 so too) */
#define MG_X 0x8051
#define MG_Z 0x8052
#define MG_DIR 0x8053
#define T_ReceivedDynamoBadge 1
#define T_ExplainDynamoBadge 2
#define T_ExplainShockWave 3
#define T_WattsonPostBattle 4
#define T_WattsonGoForth 5
#define T_GuideAdvice 6
#define T_GuidePostVictory 7
#define T_Statue 8
#define T_StatueCertified 9
#define T_BagFull 10
#define MG_WATTSON 1
#define SE_UNLOCK SEQ_SE_FLD_118        /* [guess] Sapphire's barrier sound: a Black 2 gimmick switch, audition */

    .macro MG_SHOW_LAYOUT reload        // the layout for the current state (zone init: reload 0; a switch: 1)
#if defined(MG_EVENT_ALT) && defined(MG_EVENT_OFF)
    h_goto_if_set FLAG_DEFEATED_MAUVILLE_GYM, .Lmg_off\@
    MapReplaceSetEvent MG_EVENT_OFF, 0, 0
    h_goto_if_set FLAG_MAUVILLE_GYM_BARRIERS_STATE, .Lmg_alt\@
    MapReplaceSetEvent MG_EVENT_ALT, 0, \reload
    VMJump .Lmg_end\@
.Lmg_alt\@:
    MapReplaceSetEvent MG_EVENT_ALT, 1, \reload
    VMJump .Lmg_end\@
.Lmg_off\@:
    MapReplaceSetEvent MG_EVENT_ALT, 0, 0
    MapReplaceSetEvent MG_EVENT_OFF, 1, \reload
.Lmg_end\@:
#endif
    .endm

MG_ZoneInit:                        // MauvilleCity_Gym_OnLoad (the switch states: MauvilleGymSpecial1/3 draw them)
    MG_SHOW_LAYOUT 1                // (reload: the zone's matrix is already loaded when its init runs, as Shoal Cave's)
#ifdef HOENN_TEST_CH3B
    PokePartyRecoverAll             // TEST ONLY: a full heal (PP too) for the Gym's battles
#if (HOENN_TEST_CH3B + 0) == 4 || (HOENN_TEST_CH3B + 0) == 2
    h_settrainerflag TRAINER_SHAWN  // TEST ONLY (HOENN_TEST_CH3B=4, story_fixups): the Gym's trainers count as beaten,
    h_settrainerflag TRAINER_VIVIAN //  for walking the barrier puzzle to Wattson (otherwise as stage 1); stage 2
                                    //  (Wattson beaten) too, as h_set_gym_trainers 3 leaves them
    h_settrainerflag TRAINER_BEN
    h_settrainerflag TRAINER_KIRK
#endif
#endif
    VMHalt

MG_Wattson:                         // trainerbattle_single TRAINER_WATTSON, ..., WattsonDefeated, NO_MUSIC
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_defeated TRAINER_WATTSON, L_MG_WattsonAgain
    TrainerSayMessage TRAINER_WATTSON, 0, MG_WATTSON    // I've given up on my plans to convert the city, I have. ...
    ActorMsgClose                   // (NO_MUSIC: no eye-contact music)
    h_trainerbattle TRAINER_WATTSON // (in battle: "Wahahahah! Fine, I lost! ... Take this Badge!")
    h_buffer_player                 // MauvilleCity_Gym_EventScript_WattsonDefeated
    SystemMsg T_ReceivedDynamoBadge, 2  // <player> received the Dynamo Badge from Wattson.
    h_badge_fanfare                 // Common_EventScript_PlayGymBadgeFanfare
    MsgWinCloseAll
    h_msgbox_actor T_ExplainDynamoBadge, MG_WATTSON     // With the Dynamo Badge, Pokémon can use Rock Smash ...
    h_closemessage
    h_setflag FLAG_DEFEATED_MAUVILLE_GYM
    h_givebadge 3                   // setflag FLAG_BADGE03_GET
    h_addvar VAR_PETALBURG_GYM_STATE, 1
    h_goto_if_ne VAR_PETALBURG_GYM_STATE, 6, L_MG_SetGymTrainers
    h_clearflag FLAG_HIDE_PETALBURG_GYM_GUIDE           // Common_EventScript_ReadyPetalburgGymForBattle
    h_setflag FLAG_PETALBURG_MART_EXPANDED_ITEMS
L_MG_SetGymTrainers:
    h_set_gym_trainers 3            // Kirk, Shawn, Ben and Vivian count as beaten
    MG_SHOW_LAYOUT 1                // MauvilleGymSpecial3 (every beam off) + DrawWholeMapView (drawn at the end:
    h_playse SE_UNLOCK              // Sub_MG_Redraw)
    WorkSetConst MG_REDRAW, 1
L_MG_GiveShockWave:                 // MauvilleCity_Gym_EventScript_GiveShockWave
    h_giveitem ITEM_TM34            // ITEM_TM34_SHOCK_WAVE: Shock Wave is no Gen 5 TM, so TM34 keeps its number as
    h_goto_if_eq HLIB_RESULT, 0, L_MG_BagFull   // every converter does (converter/gen_items.py: a stand-in, Sludge Wave)
    h_msgbox_actor T_ExplainShockWave, MG_WATTSON       // That TM34 there contains Shock Wave. ...
    h_setflag FLAG_RECEIVED_TM_SHOCK_WAVE
    VMJump L_MG_WattsonEnd
L_MG_BagFull:                       // Common_EventScript_ShowBagIsFull
    h_bag_is_full T_BagFull
L_MG_WattsonEnd:
    h_goto_if_ne MG_REDRAW, 1, L_MG_WattsonRelease
    VMCall Sub_MG_Redraw            // the beams off now (story_fixups)
L_MG_WattsonRelease:
    h_release
L_MG_WattsonAgain:
    WorkSetConst MG_REDRAW, 0
    h_goto_if_unset FLAG_RECEIVED_TM_SHOCK_WAVE, L_MG_GiveShockWave
    h_goto_if_eq VAR_NEW_MAUVILLE_STATE, 2, L_MG_CompletedNewMauville
    h_msgbox T_WattsonPostBattle    // I swell with optimism, seeing a promising young Trainer like you!
    h_release
L_MG_CompletedNewMauville:          // MauvilleCity_Gym_EventScript_CompletedNewMauville
    h_msgbox T_WattsonGoForth       // Wahahahah! Go forth and endeavor, youngster!
    h_release

MG_GymGuide:                        // MauvilleCity_Gym_EventScript_GymGuide
    c3_talk
    h_goto_if_set FLAG_DEFEATED_MAUVILLE_GYM, L_MG_GuidePostVictory
    h_buffer_player
    h_msgbox T_GuideAdvice          // Hey, how's it going, the Champion-bound <player>? ...
    h_release
L_MG_GuidePostVictory:
    h_msgbox T_GuidePostVictory     // Whoa, you're electrifying! You've powered the door open!
    h_release

MG_GymStatue:                       // (lockall; MSGBOX_DEFAULT)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_goto_if_badge 3, L_MG_StatueCertified
    h_msgbox_info T_Statue          // Mauville City Pokémon Gym
    h_closemessage
    h_release
L_MG_StatueCertified:
    h_buffer_player
    h_msgbox_info T_StatueCertified // Mauville City Pokémon Gym / Wattson's Certified Trainers: <player>
    h_closemessage
    h_release

// the floor switches: a switch already down, or Wattson beaten, does nothing (MauvilleCity_Gym_EventScript_
// SwitchDoNothing); otherwise VAR_MAUVILLE_GYM_STATE = the switch, every beam swaps (MauvilleGymSpecial2), the sound,
// and FLAG_MAUVILLE_GYM_BARRIERS_STATE flips (MauvilleCity_Gym_EventScript_PressFloorSwitch)
MG_Switch1:
    h_lock
    h_goto_if_set FLAG_DEFEATED_MAUVILLE_GYM, L_MG_SwitchDoNothing
    h_goto_if_eq VAR_MAUVILLE_GYM_STATE, 1, L_MG_SwitchDoNothing
    h_setvar VAR_MAUVILLE_GYM_STATE, 1
    VMJump L_MG_PressFloorSwitch
MG_Switch2:
    h_lock
    h_goto_if_set FLAG_DEFEATED_MAUVILLE_GYM, L_MG_SwitchDoNothing
    h_goto_if_eq VAR_MAUVILLE_GYM_STATE, 2, L_MG_SwitchDoNothing
    h_setvar VAR_MAUVILLE_GYM_STATE, 2
    VMJump L_MG_PressFloorSwitch
MG_Switch3:
    h_lock
    h_goto_if_set FLAG_DEFEATED_MAUVILLE_GYM, L_MG_SwitchDoNothing
    h_goto_if_eq VAR_MAUVILLE_GYM_STATE, 3, L_MG_SwitchDoNothing
    h_setvar VAR_MAUVILLE_GYM_STATE, 3
L_MG_PressFloorSwitch:
    h_goto_if_set FLAG_MAUVILLE_GYM_BARRIERS_STATE, L_MG_ClearAltState
    h_setflag FLAG_MAUVILLE_GYM_BARRIERS_STATE
    VMJump L_MG_Pressed
L_MG_ClearAltState:
    h_clearflag FLAG_MAUVILLE_GYM_BARRIERS_STATE
L_MG_Pressed:
    MG_SHOW_LAYOUT 1
    h_playse SE_UNLOCK
    VMCall Sub_MG_Redraw            // the swapped beams (story_fixups)
L_MG_SwitchDoNothing:
    h_release

// Black 2 draws a matrix that MapReplaceSetEvent swapped only on the next map change (its own scripts follow every
// in-field MapReplaceSetEvent with a MapChangeCore: 0240.s, 0926.s), and MapChangeCore takes constants only (ov036
// s00C4_MapChangeCore reads its arguments with VM_Read16): a fade and a map change to the player's own tile and facing,
// for the tiles where the layout changes (the three switches, the three tiles beside Wattson). The map change starts
// when the calling script ends (GameEvent_ChainNext); the zone init then loads the new layout and the reserved
// MG_FadeIn (script 9) fades the screen in. story_fixups 2026-10-07.
    .macro MG_WARP_HERE x, z            // zone tile; facing from MG_DIR (0 up, 1 down, 2 left, 3 right)
    RTReserveScript 9               // MG_FadeIn on arrival: a scripted map change after FadeOutBlack stays black
    h_goto_if_ne MG_DIR, 0, .Lmw1\@     // until a script fades in (Black 2's 0240.s / 0926.s reserve one too)
    MapChangeCore 239, \x, 0, \z, 0
    VMReturn
.Lmw1\@:
    h_goto_if_ne MG_DIR, 1, .Lmw2\@
    MapChangeCore 239, \x, 0, \z, 1
    VMReturn
.Lmw2\@:
    h_goto_if_ne MG_DIR, 2, .Lmw3\@
    MapChangeCore 239, \x, 0, \z, 2
    VMReturn
.Lmw3\@:
    MapChangeCore 239, \x, 0, \z, 3
    VMReturn
    .endm
    .macro MG_IF_AT x, z, label
    WorkCmpConst MG_X, \x
    VMJumpIf CMP_NE, .Lmi\@
    h_goto_if_eq MG_Z, \z, \label
.Lmi\@:
    .endm

MG_FadeIn:
    FadeInBlack
    FadeWait
    VMHalt

Sub_MG_Redraw:
// >>> emerald_rooms mauville_redraw_jump (b2tools/emerald_rooms.py / emerald_gyms.py write this block on every run: edit the generator)
#ifdef HOENN_EMERALD
    VMJump Sub_MG_RedrawEm          // Emerald: its switches and Wattson's tiles
#endif
// <<< emerald_rooms mauville_redraw_jump
    PlayerGetGPos MG_X, MG_Z
    PlayerGetDir MG_DIR
    FadeOutBlack
    FadeWait
    MG_IF_AT 1, 9, L_MG_AtSwitch1   // zone tiles = Sapphire tiles + (1,0)
    MG_IF_AT 9, 11, L_MG_AtSwitch2
    MG_IF_AT 5, 15, L_MG_AtSwitch3
    MG_IF_AT 4, 3, L_MG_AtWattsonW
    MG_IF_AT 6, 3, L_MG_AtWattsonE
    MG_IF_AT 5, 4, L_MG_AtWattsonS
    FadeInBlack                     // elsewhere: the new layout shows on the next visit
    FadeWait
    VMReturn
L_MG_AtSwitch1:
    MG_WARP_HERE 1, 9
L_MG_AtSwitch2:
    MG_WARP_HERE 9, 11
L_MG_AtSwitch3:
    MG_WARP_HERE 5, 15
L_MG_AtWattsonW:
    MG_WARP_HERE 4, 3
L_MG_AtWattsonE:
    MG_WARP_HERE 6, 3
L_MG_AtWattsonS:
    MG_WARP_HERE 5, 4
    .balign 4, 0

// >>> emerald_rooms mauville_em (b2tools/emerald_rooms.py / emerald_gyms.py write this block on every run: edit the generator)
#ifdef HOENN_EMERALD
MG_Switch4Em:                           // MauvilleCity_Gym_EventScript_Switch4 (Emerald's fourth switch, VAR_MAUVILLE_GYM_STATE 4)
    h_lock
    h_goto_if_set FLAG_DEFEATED_MAUVILLE_GYM, L_MG_SwitchDoNothing
    h_goto_if_eq VAR_MAUVILLE_GYM_STATE, 4, L_MG_SwitchDoNothing
    h_setvar VAR_MAUVILLE_GYM_STATE, 4
    VMJump L_MG_PressFloorSwitch
Sub_MG_RedrawEm:                        // Sub_MG_Redraw on Emerald's tiles (zone tiles = Emerald tiles + (1,0))
    PlayerGetGPos MG_X, MG_Z
    PlayerGetDir MG_DIR
    FadeOutBlack
    FadeWait
    MG_IF_AT 1, 15, L_MG_EmAt1          // the switches (0,15) (4,12) (3,9) (8,9)
    MG_IF_AT 5, 12, L_MG_EmAt2
    MG_IF_AT 4, 9, L_MG_EmAt3
    MG_IF_AT 9, 9, L_MG_EmAt4
    MG_IF_AT 5, 2, L_MG_EmAtWattsonW    // beside Wattson (5,2): west (4,2), south (5,3)
    MG_IF_AT 6, 3, L_MG_EmAtWattsonS
    FadeInBlack
    FadeWait
    VMReturn
L_MG_EmAt1:
    MG_WARP_HERE 1, 15
L_MG_EmAt2:
    MG_WARP_HERE 5, 12
L_MG_EmAt3:
    MG_WARP_HERE 4, 9
L_MG_EmAt4:
    MG_WARP_HERE 9, 9
L_MG_EmAtWattsonW:
    MG_WARP_HERE 5, 2
L_MG_EmAtWattsonS:
    MG_WARP_HERE 6, 3
    .balign 4, 0
#endif
// <<< emerald_rooms mauville_em
